CREATE TABLE schema_migrations (version integer PRIMARY KEY, checksum text NOT NULL, applied_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE worlds (id integer PRIMARY KEY CHECK(id=1), epoch bigint NOT NULL DEFAULT 0, seq bigint NOT NULL DEFAULT 0, rules_hash text NOT NULL, map_hash text NOT NULL, state jsonb NOT NULL);
CREATE TABLE portals (id text PRIMARY KEY, state jsonb NOT NULL);
CREATE TABLE accounts (id uuid PRIMARY KEY, state jsonb NOT NULL, recovery_hash text UNIQUE NOT NULL, init_hash text UNIQUE NOT NULL, created_at bigint NOT NULL);
CREATE TABLE sessions (token_hash text PRIMARY KEY, account_id uuid NOT NULL REFERENCES accounts(id), expires_at bigint NOT NULL);
CREATE INDEX sessions_account ON sessions(account_id);
CREATE TABLE command_receipts (actor text NOT NULL, request_id uuid NOT NULL, digest text NOT NULL, result jsonb NOT NULL, seq bigint NOT NULL, created_at bigint NOT NULL, PRIMARY KEY(actor,request_id));
CREATE TABLE outbox (seq bigint PRIMARY KEY, event jsonb NOT NULL, created_at bigint NOT NULL);
CREATE TABLE checkpoints (season_id integer NOT NULL, checkpoint_index integer NOT NULL, at_ms bigint NOT NULL, scores jsonb NOT NULL, PRIMARY KEY(season_id,checkpoint_index));
CREATE TABLE seasons (id integer PRIMARY KEY, start_at bigint NOT NULL, end_at bigint NOT NULL, scores jsonb NOT NULL);
CREATE TABLE applications (id uuid PRIMARY KEY, account_id uuid NOT NULL REFERENCES accounts(id), state jsonb NOT NULL, created_at bigint NOT NULL);
CREATE INDEX applications_account ON applications(account_id);
CREATE TABLE complaints (id uuid PRIMARY KEY, account_id uuid NOT NULL REFERENCES accounts(id), state jsonb NOT NULL, created_at bigint NOT NULL);
CREATE TABLE admin_audit (id bigserial PRIMARY KEY, actor text NOT NULL, action text NOT NULL, reason text NOT NULL, detail jsonb NOT NULL, seq bigint NOT NULL, created_at bigint NOT NULL);
CREATE TABLE admin_sessions (token_hash text PRIMARY KEY, expires_at bigint NOT NULL);
CREATE TABLE markers (id uuid PRIMARY KEY, faction text NOT NULL, account_id uuid NOT NULL, portal_id text NOT NULL, expires_at bigint NOT NULL);
CREATE TABLE alerts (id bigserial PRIMARY KEY, account_id uuid NOT NULL REFERENCES accounts(id), portal_id text NOT NULL, count integer NOT NULL DEFAULT 1, first_at bigint NOT NULL, last_at bigint NOT NULL);
CREATE INDEX alerts_account ON alerts(account_id,last_at);
CREATE TABLE operations (name text PRIMARY KEY, value jsonb NOT NULL);
